  /// is returned and `NULL` is put in @out_transform.
  static final _gskTransformParse =
      gsk4Lookup<
            ffi.NativeFunction<
              ffi.Int32 Function(ffi.Pointer<Utf8>, ffi.Pointer<ffi.Void>)
